<?php
namespace App\Services;use App\Models\Applicant;
final class NotificationTemplateService { private const DEFAULTS=['registration_created'=>'Pendaftaran {registration_number} atas nama {full_name} berhasil diterima.','payment_paid'=>'Pembayaran {registration_number} telah berhasil.','document_incomplete'=>'Berkas {registration_number} perlu diperbaiki.','document_complete'=>'Berkas {registration_number} telah lengkap.','test_scheduled'=>'Jadwal tes {registration_number} tersedia.','selection_passed'=>'Selamat, {full_name} dinyatakan diterima.','selection_not_passed'=>'Hasil seleksi {registration_number} tersedia.'];public function __construct(private SettingsService $settings){}public function all():array{return collect(self::DEFAULTS)->mapWithKeys(fn($v,$k)=>[$k=>$this->settings->get('notifications.'.$k,$v)])->all();}public function render(string $event,Applicant $a,?string $fallback=null):string{$template=$this->settings->get('notifications.'.$event,self::DEFAULTS[$event]??$fallback??'Pembaruan status PMB tersedia.');return strtr($template,['{registration_number}'=>$a->registration_number,'{full_name}'=>$a->full_name,'{payment_status}'=>$a->payment_status->value,'{document_status}'=>$a->document_status->value,'{selection_status}'=>$a->selection_status->value]);}}
